class Book:
    def __init__(self, title):
        self.title = title
        self.available = True

    def borrow(self):
        if not self.available:
            return False
        self.available = False
        return True

    def return_book(self):
        self.available = True


first = Book("Python")
second = Book("Алгоритмы")

print(first.borrow())       # True
print(first.borrow())       # False
print(second.available)     # True
